/// <summary>
/// Creates a string from 3 LogisticsLocationNames
/// </summary>
/// <returns>LogisticsInvoiceName</returns>
public LogisticsInvoiceName avaName()
{
    LogisticsInvoiceName avaNameLoc;

    if(this.NDXLogisticsLocationName1)
    {
        avaNameLoc = this.NDXLogisticsLocationName1;
    }

    if(this.NDXLogisticsLocationName2)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += this.NDXLogisticsLocationName2;
    }

    if(this.NDXLogisticsLocationName3)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += this.NDXLogisticsLocationName3;
    }

    return avaNameLoc;
}
